"A page that stays in the top 30 for many days shows lasting interest. A one-day jump is usually a moment, not a trend.": "Uma página que fica no top 30 por muitos dias mostra interesse duradouro. Um salto de um dia costuma ser um momento, não uma tendência.",
"New entries are early signals. Wait to see if they stay next week before acting on them.": "Novidades são sinais iniciais. Espere para ver se continuam na semana seguinte antes de agir.",
"Percentages show shares, not size. 20% of a big country's news can be more articles than 80% of a small one's.": "Porcentagens mostram fatias, não tamanho. 20% das notícias de um país grande podem ser mais matérias que 80% das de um país pequeno.",
"Two countries in the same story doesn't mean they get along. It can be trade, sport or a conflict.": "Dois países na mesma notícia não quer dizer que se dão bem. Pode ser comércio, esporte ou um conflito.",
"Compare like with like: same days, same source, same measure. Otherwise the comparison lies.": "Compare igual com igual: mesmos dias, mesma fonte, mesma medida. Senão a comparação engana.",
"Where people read is a hint of where fans or customers are, not proof.": "Onde as pessoas leem é uma pista de onde estão fãs ou clientes, não uma prova.",
"More days in a country's top 30 means steady interest there, not just one viral moment.": "Mais dias no top 30 de um país significam interesse constante ali, não só um momento viral.",
