"Times a Wikipedia page was opened from that country. Wikimedia rounds them up a little to protect privacy.": "Vezes que uma página da Wikipédia foi aberta no país. A Wikimedia arredonda um pouco para proteger a privacidade.",
"Days in the top 30": "Dias no top 30",
"On how many recorded days the page was among the country's 30 most-read. More days means lasting interest, not a one-day spike.": "Em quantos dias registrados a página esteve entre as 30 mais lidas do país. Mais dias indica interesse duradouro.",
"Online news articles worldwide that mention the country, counted by The GDELT Project. One article can count for two countries.": "Notícias online no mundo que citam o país, contadas pelo The GDELT Project. Uma notícia pode contar para dois países.",
"Peaceful and tense news": "Notícias pacíficas e tensas",
"GDELT sorts every news event into 20 types. Talks, deals and aid count as peaceful. Protests and fighting count as tension or conflict.": "O GDELT classifica cada evento em 20 tipos. Conversas, acordos e ajuda contam como pacíficos. Protestos e combates contam como tensão ou conflito.",
"Period": "Período",
"Each report covers up to the last 30 recorded days.": "Cada relatório cobre até os últimos 30 dias registrados.",
"Sources and limits": "Fontes e limites",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). Ideas are written by AI (Google Gemini) and can contain mistakes. YouTube and news headlines are not part of the report.": "Feito pelo Like Polling a partir dos seus registros diários de dados abertos: visualizações da Wikipédia (Wikimedia Foundation) e temas e países das notícias (The GDELT Project). As ideias são escritas por IA (Google Gemini) e podem ter erros. YouTube e manchetes não fazem parte do relatório.",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). YouTube and news headlines are not part of the report.": "Feito pelo Like Polling a partir dos seus registros diários de dados abertos: visualizações da Wikipédia (Wikimedia Foundation) e temas e países das notícias (The GDELT Project). YouTube e manchetes não fazem parte do relatório.",
