"A sponsor pays to be seen by a person's fans. The more people read about that person, in more languages, the further the brand travels.": "Un patrocinador paga para que lo vean los fans de una persona. Cuanta más gente lee sobre esa persona, en más idiomas, más lejos llega la marca.",
"Extended Brand Report": "Informe ampliado de marca",
