"At a glance": "De un vistazo",
"The main numbers for the period, explained in the sections below.": "Los números principales del periodo, explicados abajo.",
"News coverage per day": "Cobertura informativa por día",
"How many news articles worldwide mentioned the country each day. Spikes usually mean a big event.": "Cuántas noticias en el mundo mencionaron al país cada día. Los picos suelen indicar un gran evento.",
"Busiest day: {day} with {n} articles": "Día más intenso: {day}, con {n} noticias",
