". Average: {n} a day.": ". Promedio: {n} al día.",
"Wikipedia attention per day": "Atención en Wikipedia por día",
"Total views of the 30 most-read pages each day. It shows how busy people were looking things up.": "Visitas totales de las 30 páginas más leídas cada día. Muestra cuánto buscó la gente.",
"The #1 page, {title}, had {n} views: {p}% of all top-30 views in the period.": "La página n.º 1, {title}, tuvo {n} visitas: el {p}% de todas las del top 30 en el periodo.",
"Most-read on Wikipedia": "Lo más leído en Wikipedia",
"Total views over the period. The small line shows that page's views day by day.": "Visitas totales del periodo. La línea muestra las visitas día a día.",
"Rising this week": "En alza esta semana",
