"How to read the numbers": "Cómo leer los números",
"Views": "Visitas",
"Times a Wikipedia page was opened from that country. Wikimedia rounds them up a little to protect privacy.": "Veces que se abrió una página de Wikipedia desde ese país. Wikimedia las redondea un poco por privacidad.",
"Days in the top 30": "Días en el top 30",
"On how many recorded days the page was among the country's 30 most-read. More days means lasting interest, not a one-day spike.": "En cuántos días registrados la página estuvo entre las 30 más leídas del país. Más días indica interés duradero.",
"Online news articles worldwide that mention the country, counted by The GDELT Project. One article can count for two countries.": "Noticias en línea de todo el mundo que mencionan al país, contadas por The GDELT Project. Una noticia puede contar para dos países.",
"Peaceful and tense news": "Noticias pacíficas y tensas",
"GDELT sorts every news event into 20 types. Talks, deals and aid count as peaceful. Protests and fighting count as tension or conflict.": "GDELT clasifica cada evento en 20 tipos. Diálogos, acuerdos y ayuda cuentan como pacíficos. Protestas y combates cuentan como tensión o conflicto.",
"Period": "Periodo",
"Each report covers up to the last 30 recorded days.": "Cada informe cubre hasta los últimos 30 días registrados.",
"Sources and limits": "Fuentes y límites",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). Ideas are written by AI (Google Gemini) and can contain mistakes. YouTube and news headlines are not part of the report.": "Hecho por Like Polling con sus registros diarios de datos abiertos: visitas de Wikipedia (Wikimedia Foundation) y temas y países de las noticias (The GDELT Project). Las ideas las escribe una IA (Google Gemini) y pueden tener errores. YouTube y los titulares no forman parte del informe.",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). YouTube and news headlines are not part of the report.": "Hecho por Like Polling con sus registros diarios de datos abiertos: visitas de Wikipedia (Wikimedia Foundation) y temas y países de las noticias (The GDELT Project). YouTube y los titulares no forman parte del informe.",
