"A good number always compares: more than what, since when, out of how many? Ask that about every stat you see online.": "Eine gute Zahl vergleicht immer: mehr als was, seit wann, von wie vielen? Frag das bei jeder Statistik, die du online siehst.",
"One big number means little on its own. Compare it with another country, another week or another brand.": "Eine große Zahl allein sagt wenig. Vergleiche sie mit einem anderen Land, einer anderen Woche oder einer anderen Marke.",
"In a line chart, look for spikes, not exact numbers. A spike is a day very different from the rest: check the news for that day.": "Achte im Liniendiagramm auf Spitzen, nicht auf genaue Zahlen. Eine Spitze ist ein Tag, der stark abweicht: Schau dir die Nachrichten dieses Tages an.",
"A page that stays in the top 30 for many days shows lasting interest. A one-day jump is usually a moment, not a trend.": "Eine Seite, die viele Tage in den Top 30 bleibt, zeigt anhaltendes Interesse. Ein Sprung an einem Tag ist meist ein Moment, kein Trend.",
"New entries are early signals. Wait to see if they stay next week before acting on them.": "Neueinsteiger sind frühe Signale. Warte ab, ob sie nächste Woche noch da sind, bevor du handelst.",
"Percentages show shares, not size. 20% of a big country's news can be more articles than 80% of a small one's.": "Prozente zeigen Anteile, nicht Größe. 20 % der Nachrichten eines großen Landes können mehr Artikel sein als 80 % eines kleinen.",
"Two countries in the same story doesn't mean they get along. It can be trade, sport or a conflict.": "Zwei Länder in derselben Meldung heißt nicht, dass sie sich gut verstehen. Es kann Handel, Sport oder ein Konflikt sein.",
"Compare like with like: same days, same source, same measure. Otherwise the comparison lies.": "Vergleiche Gleiches mit Gleichem: gleiche Tage, gleiche Quelle, gleiches Maß. Sonst lügt der Vergleich.",
"Where people read is a hint of where fans or customers are, not proof.": "Wo Menschen lesen, ist ein Hinweis darauf, wo Fans oder Kunden sind, kein Beweis.",
"More days in a country's top 30 means steady interest there, not just one viral moment.": "Mehr Tage in den Top 30 eines Landes bedeuten dort beständiges Interesse, nicht nur einen viralen Moment.",
