"Times a Wikipedia page was opened from that country. Wikimedia rounds them up a little to protect privacy.": "Wie oft eine Wikipedia-Seite aus dem Land geöffnet wurde. Wikimedia rundet leicht auf, zum Schutz der Privatsphäre.",
"Days in the top 30": "Tage in den Top 30",
"On how many recorded days the page was among the country's 30 most-read. More days means lasting interest, not a one-day spike.": "An wie vielen Tagen die Seite zu den 30 meistgelesenen gehörte. Mehr Tage heißt anhaltendes Interesse.",
"Online news articles worldwide that mention the country, counted by The GDELT Project. One article can count for two countries.": "Online-Artikel weltweit, die das Land nennen, gezählt von The GDELT Project. Ein Artikel kann für zwei Länder zählen.",
"Peaceful and tense news": "Friedliche und angespannte Nachrichten",
"GDELT sorts every news event into 20 types. Talks, deals and aid count as peaceful. Protests and fighting count as tension or conflict.": "GDELT ordnet jedes Ereignis in 20 Typen ein. Gespräche, Abkommen und Hilfe gelten als friedlich. Proteste und Kämpfe gelten als Spannung oder Konflikt.",
"Period": "Zeitraum",
"Each report covers up to the last 30 recorded days.": "Jeder Bericht umfasst bis zu 30 aufgezeichnete Tage.",
"Sources and limits": "Quellen und Grenzen",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). Ideas are written by AI (Google Gemini) and can contain mistakes. YouTube and news headlines are not part of the report.": "Erstellt von Like Polling aus eigenen täglichen Aufzeichnungen offener Daten: Wikipedia-Aufrufe (Wikimedia Foundation) sowie Nachrichtenthemen und Länder (The GDELT Project). Die Ideen schreibt KI (Google Gemini), sie können Fehler enthalten. YouTube und Schlagzeilen sind nicht Teil des Berichts.",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). YouTube and news headlines are not part of the report.": "Erstellt von Like Polling aus eigenen täglichen Aufzeichnungen offener Daten: Wikipedia-Aufrufe (Wikimedia Foundation) sowie Nachrichtenthemen und Länder (The GDELT Project). YouTube und Schlagzeilen sind nicht Teil des Berichts.",
