"People it sponsors": "Кого спонсирует",
"Athletes and stars who name {s} as a sponsor on Wikipedia, ranked by English Wikipedia views, last 30 days.": "Спортсмены и звёзды, указывающие {s} как спонсора в Википедии, по просмотрам английской Википедии за 30 дней.",
"{a} is the most-read of them, with {n} views.": "{a} читают больше всех: {n} просмотров.",
"Sponsors: Wikipedia infoboxes.": "Спонсоры: карточки Википедии.",
"A sponsor pays to be seen by a person's fans. The more people read about that person, in more languages, the further the brand travels.": "Спонсор платит, чтобы его видели фанаты человека. Чем больше людей читают о нём и на большем числе языков, тем дальше доходит бренд.",
"Extended Brand Report": "Расширенный отчёт о бренде",
"No Wikipedia page of its own yet. This report shows what the open web says about it.": "Своей страницы в Википедии пока нет. Отчёт показывает, что о бренде говорит открытый интернет.",
"1 person names {s} as a sponsor on Wikipedia.": "1 человек указывает {s} как спонсора в Википедии.",
