"News coverage per day": "Новости по дням",
"How many news articles worldwide mentioned the country each day. Spikes usually mean a big event.": "Сколько статей в мире упоминали страну каждый день. Пики обычно означают крупное событие.",
"Busiest day: {day} with {n} articles": "Самый насыщенный день: {day}, {n} статей",
