". Average: {n} a day.": ". В среднем: {n} в день.",
"Wikipedia attention per day": "Внимание в Википедии по дням",
"Total views of the 30 most-read pages each day. It shows how busy people were looking things up.": "Сумма просмотров 30 самых читаемых страниц за день. Показывает, сколько люди искали.",
"The #1 page, {title}, had {n} views: {p}% of all top-30 views in the period.": "Страница №1, {title}, — {n} просмотров: {p}% всех просмотров топ-30 за период.",
"Most-read on Wikipedia": "Самое читаемое в Википедии",
"Total views over the period. The small line shows that page's views day by day.": "Просмотры за период. Линия показывает просмотры по дням.",
"Rising this week": "Растёт на этой неделе",
"Pages that entered the daily top 30 only in the last 7 days. Often the best early signals.": "Страницы, попавшие в топ-30 только за последние 7 дней. Часто лучшие ранние сигналы.",
"{d} of {t} days in the daily top 30 · first seen {day}": "{d} из {t} дней в топ-30 · впервые {day}",
"What the news talks about": "О чём говорят новости",
"Share of all news articles about the country, by type of event.": "Доля статей о стране по типу события.",
"peaceful": "мирные",
"tension or conflict": "напряжённость или конфликт",
"The most common type was {t}, at {p}% of {n} articles.": "Чаще всего: {t} — {p}% из {n} статей.",
"In the news with": "В новостях вместе с",
"Countries that appeared in the same news articles most often. A sign of who the country deals with.": "Страны, чаще всего упоминавшиеся в тех же статьях. Показывает, с кем страна имеет дело.",
"Ideas to copy": "Идеи для заимствования",
