"How to read the numbers": "Как читать цифры",
"Views": "Просмотры",
"Times a Wikipedia page was opened from that country. Wikimedia rounds them up a little to protect privacy.": "Сколько раз страницу Википедии открыли из страны. Wikimedia немного округляет ради приватности.",
"Days in the top 30": "Дни в топ-30",
"On how many recorded days the page was among the country's 30 most-read. More days means lasting interest, not a one-day spike.": "Сколько дней страница была в 30 самых читаемых в стране. Больше дней — устойчивый интерес.",
"Online news articles worldwide that mention the country, counted by The GDELT Project. One article can count for two countries.": "Онлайн-статьи по всему миру с упоминанием страны, по подсчёту The GDELT Project. Одна статья может учитываться для двух стран.",
"Peaceful and tense news": "Мирные и напряжённые новости",
"GDELT sorts every news event into 20 types. Talks, deals and aid count as peaceful. Protests and fighting count as tension or conflict.": "GDELT делит события на 20 типов. Переговоры, сделки и помощь считаются мирными. Протесты и бои считаются напряжённостью или конфликтом.",
"Period": "Период",
"Each report covers up to the last 30 recorded days.": "Каждый отчёт охватывает до 30 последних записанных дней.",
"Sources and limits": "Источники и ограничения",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). Ideas are written by AI (Google Gemini) and can contain mistakes. YouTube and news headlines are not part of the report.": "Создано Like Polling по собственным ежедневным записям открытых данных: просмотры Википедии (Wikimedia Foundation), темы и страны новостей (The GDELT Project). Идеи пишет ИИ (Google Gemini), возможны ошибки. YouTube и заголовки новостей в отчёт не входят.",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). YouTube and news headlines are not part of the report.": "Создано Like Polling по собственным ежедневным записям открытых данных: просмотры Википедии (Wikimedia Foundation), темы и страны новостей (The GDELT Project). YouTube и заголовки новостей в отчёт не входят.",
