". Average: {n} a day.": ". У середньому: {n} на день.",
"Wikipedia attention per day": "Увага у Вікіпедії за днями",
"Total views of the 30 most-read pages each day. It shows how busy people were looking things up.": "Сума переглядів 30 найпопулярніших сторінок за день. Показує, скільки люди шукали.",
"The #1 page, {title}, had {n} views: {p}% of all top-30 views in the period.": "Сторінка №1, {title}, — {n} переглядів: {p}% усіх переглядів топ-30 за період.",
"Most-read on Wikipedia": "Найпопулярніше у Вікіпедії",
"Total views over the period. The small line shows that page's views day by day.": "Перегляди за період. Лінія показує перегляди за днями.",
"Rising this week": "Зростає цього тижня",
"Pages that entered the daily top 30 only in the last 7 days. Often the best early signals.": "Сторінки, що потрапили до топ-30 лише за останні 7 днів. Часто найкращі ранні сигнали.",
"{d} of {t} days in the daily top 30 · first seen {day}": "{d} з {t} днів у топ-30 · уперше {day}",
"What the news talks about": "Про що говорять новини",
"Share of all news articles about the country, by type of event.": "Частка статей про країну за типом події.",
"peaceful": "мирні",
"tension or conflict": "напруга чи конфлікт",
"The most common type was {t}, at {p}% of {n} articles.": "Найчастіше: {t} — {p}% із {n} статей.",
"In the news with": "У новинах разом із",
"Countries that appeared in the same news articles most often. A sign of who the country deals with.": "Країни, що найчастіше згадувалися в тих самих статтях. Показує, з ким країна має справу.",
"Ideas to copy": "Ідеї для запозичення",
"Written each week by AI from the data above. Use them as starting points.": "Щотижня пише ШІ за даними вище. Використовуйте як відправну точку.",
"Based on: {x}": "На основі: {x}",
"This week's ideas are being written. Check back soon.": "Ідеї цього тижня готуються. Завітайте пізніше.",
"How to read the numbers": "Як читати цифри",
"Views": "Перегляди",
"Times a Wikipedia page was opened from that country. Wikimedia rounds them up a little to protect privacy.": "Скільки разів сторінку Вікіпедії відкрили з країни. Wikimedia трохи округлює заради приватності.",
"Days in the top 30": "Дні в топ-30",
"On how many recorded days the page was among the country's 30 most-read. More days means lasting interest, not a one-day spike.": "Скільки днів сторінка була серед 30 найпопулярніших у країні. Більше днів — стійкий інтерес.",
"Online news articles worldwide that mention the country, counted by The GDELT Project. One article can count for two countries.": "Онлайн-статті у світі зі згадкою країни, за підрахунком The GDELT Project. Одна стаття може рахуватися для двох країн.",
"Peaceful and tense news": "Мирні та напружені новини",
"GDELT sorts every news event into 20 types. Talks, deals and aid count as peaceful. Protests and fighting count as tension or conflict.": "GDELT ділить події на 20 типів. Переговори, угоди й допомога вважаються мирними. Протести й бої вважаються напругою або конфліктом.",
"Period": "Період",
"Each report covers up to the last 30 recorded days.": "Кожен звіт охоплює до 30 останніх записаних днів.",
"Sources and limits": "Джерела та обмеження",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). Ideas are written by AI (Google Gemini) and can contain mistakes. YouTube and news headlines are not part of the report.": "Створено Like Polling за власними щоденними записами відкритих даних: перегляди Вікіпедії (Wikimedia Foundation), теми й країни новин (The GDELT Project). Ідеї пише ШІ (Google Gemini), можливі помилки. YouTube і заголовки новин до звіту не входять.",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). YouTube and news headlines are not part of the report.": "Створено Like Polling за власними щоденними записами відкритих даних: перегляди Вікіпедії (Wikimedia Foundation), теми й країни новин (The GDELT Project). YouTube і заголовки новин до звіту не входять.",
