"Extended Company Report": "확장 기업 리포트",
"Gathered since day one.": "첫날부터 모은 데이터.",
"Like Polling has recorded its sources every day since {date}, the day we started.": "Like Polling은 시작한 날인 {date}부터 매일 출처를 기록하고 있습니다.",
"Every number below comes from those records.": "아래 모든 숫자는 이 기록에서 나옵니다.",
