"Athletes and stars who name {s} as a sponsor on Wikipedia, ranked by English Wikipedia views, last 30 days.": "ウィキペディアで{s}をスポンサーに挙げるアスリートやスター。英語版ウィキペディアの閲覧数順、過去30日。",
