"A sponsor pays to be seen by a person's fans. The more people read about that person, in more languages, the further the brand travels.": "スポンサーは、その人のファンに見てもらうためにお金を払います。その人がより多くの人に、より多くの言語で読まれるほど、ブランドは遠くまで届きます。",
