"In {y}, it lost money.": "{y}年は赤字でした。",
"Sales are all the money customers paid. Profit is what is left after every cost and tax. High sales with low profit can still be a weak year.": "売上高は顧客が支払ったお金の合計です。利益はすべての費用と税金を引いた残りです。売上が大きくても利益が小さければ、弱い年のこともあります。",
"Sales and profit: US SEC filings (EDGAR), public data.": "売上高と利益：米国SECへの提出書類（EDGAR）、公開データ。",
"Sales, US$": "売上高（ドル）",
