"Date": "日付",
"Holiday": "祝日",
"Name in English": "英語名",
"Compare with real rivals, not with everyone. A small brand can lead its niche and still look tiny next to the giants.": "比べる相手は全員ではなく本当のライバル。小さなブランドでも自分の分野ではトップになれますが、大手の横では小さく見えます。",
"GDP is the size of a whole economy, not how rich each person is. For that, look at GDP per person.": "GDPは経済全体の大きさで、一人ひとりの豊かさではありません。それを見るなら一人あたりGDPを。",
"growth of {c}'s economy in {y}, after inflation.": "{y}年の{c}の経済成長率(インフレ調整後)。",
"change in {c}'s economy in {y}, after inflation: it shrank.": "{y}年の{c}の経済の変化(インフレ調整後):縮小しました。",
