"Growth after inflation": "成長率(インフレ調整後)",
"The economy": "経済",
"Year": "年",
"Yearly figures from the World Bank. The newest year is usually last year.": "世界銀行の年次データ。最新の年は通常、昨年です。",
"GDP": "GDP",
"Gross domestic product: the value of everything a country produces in a year. GDP per person is that value divided by the population. From the World Bank.": "国内総生産:国が1年間に生み出したすべての価値。一人あたりGDPはそれを人口で割ったもの。出典:世界銀行。",
"GDP figures come from the World Bank's open data.": "GDPの数値は世界銀行のオープンデータによるものです。",
"In its field": "同じ分野で",
"{s} is #{r} of {n} in {f}, with {p}% of the attention.": "{s}は「{f}」の{n}件中{r}位で、注目の{p}%を集めています。",
"Its views changed {a} this month; the whole field changed {b}.": "今月の閲覧数の変化は{a}、分野全体では{b}でした。",
"Top in its field": "分野のトップ",
"{f}: the {n} biggest pages in this Wikipedia category, ranked by English Wikipedia views, last 30 days.": "{f}:このWikipediaカテゴリーの主要{n}ページ。直近30日の英語版Wikipedia閲覧数順。",
"{s} in {f}, by Wikipedia views.": "Wikipedia閲覧数で見た「{f}」での{s}の順位。",
"almost all": "ほぼすべて",
"fewer than 1 in 10": "1割未満",
"{n} in 10": "{n}割",
"Learn": "ヒント",
"In plain words": "かんたんに言うと",
"The report in a few easy numbers. The slides after this show the details.": "レポートをいくつかのわかりやすい数字で。詳しくは次のスライドから。",
"{a} was in the news {x}× as much as {b}.": "{a}は{b}の{x}倍ニュースに登場しました。",
"news stories about {c} were peaceful: talks, deals or aid.": "{c}に関するニュースが平和的な内容でした（対話・合意・支援）。",
"On {day}, news about {c} was {x}× a normal day. Something big happened.": "{day}、{c}に関するニュースは普段の{x}倍でした。何か大きな出来事がありました。",
"of top-30 views in {c} went to one page: {t}.": "{c}のトップ30の閲覧数が1つのページに集中：{t}。",
"People in {c} cared most about {t}.": "{c}の人々がいちばん関心を持ったのは{t}。",
"{t} is the newest big interest in {c}.": "{t}は{c}で最も新しい大きな関心事です。",
"{p} shows up next to {c} in the news more than any other country.": "{p}は他のどの国よりもニュースで{c}と一緒に登場します。",
"What this means": "つまりどういうこと？",
"{s} is followed most in {c}.": "{s}が最も注目されているのは{c}です。",
"readers of {s} used a language other than English.": "{s}の読者が英語以外の言語で読みました。",
"{s} had {x}× the views of {b}, the next most-viewed.": "{s}の閲覧数は次点の{b}の{x}倍でした。",
"On {day}, views of {s} were {x}× a normal day.": "{day}、{s}の閲覧数は普段の{x}倍でした。",
"more Wikipedia views for {s} than the month before.": "{s}のWikipedia閲覧数が前月より増えました。",
"fewer Wikipedia views for {s} than the month before.": "{s}のWikipedia閲覧数が前月より減りました。",
"{s} among similar artists, by views.": "閲覧数で見た、似たアーティストの中での{s}の順位。",
"{s} among similar brands, by views.": "閲覧数で見た、似たブランドの中での{s}の順位。",
"A good number always compares: more than what, since when, out of how many? Ask that about every stat you see online.": "良い数字は必ず比べています。何と比べて？いつから？何件中？ネットで見るすべての統計にこう問いかけましょう。",
"One big number means little on its own. Compare it with another country, another week or another brand.": "大きな数字ひとつだけでは意味がありません。他の国、他の週、他のブランドと比べましょう。",
"In a line chart, look for spikes, not exact numbers. A spike is a day very different from the rest: check the news for that day.": "折れ線グラフでは正確な数字より急上昇を見ましょう。急上昇は他と大きく違う日です。その日のニュースを確認しましょう。",
"A page that stays in the top 30 for many days shows lasting interest. A one-day jump is usually a moment, not a trend.": "何日もトップ30に残るページは長続きする関心を示します。1日だけの急上昇はたいていトレンドではなく一瞬です。",
"New entries are early signals. Wait to see if they stay next week before acting on them.": "新しく入ったものは早いサインです。行動する前に、翌週も残っているか確かめましょう。",
"Percentages show shares, not size. 20% of a big country's news can be more articles than 80% of a small one's.": "パーセントは割合で、量ではありません。大きな国のニュースの20%が、小さな国の80%より記事数が多いこともあります。",
"Two countries in the same story doesn't mean they get along. It can be trade, sport or a conflict.": "2つの国が同じ記事に出ても、仲が良いとは限りません。貿易、スポーツ、対立の場合もあります。",
"Compare like with like: same days, same source, same measure. Otherwise the comparison lies.": "同じ条件で比べましょう。同じ期間、同じ情報源、同じ指標。そうでないと比較はウソをつきます。",
"Where people read is a hint of where fans or customers are, not proof.": "どこで読まれているかは、ファンや顧客がどこにいるかのヒントであって、証拠ではありません。",
"More days in a country's top 30 means steady interest there, not just one viral moment.": "ある国のトップ30に長くいるほど、一度のバズではなく安定した関心を意味します。",
