"Rising this week": "今週の急上昇",
"Pages that entered the daily top 30 only in the last 7 days. Often the best early signals.": "直近7日で初めて上位30に入ったページ。早いシグナルになりがちです。",
"{d} of {t} days in the daily top 30 · first seen {day}": "{t}日中{d}日が上位30 · 初登場 {day}",
"What the news talks about": "ニュースの話題",
"Share of all news articles about the country, by type of event.": "この国の記事の出来事タイプ別の割合。",
"peaceful": "平和的",
"tension or conflict": "緊張・対立",
"The most common type was {t}, at {p}% of {n} articles.": "最も多かったのは{t}で、{n}件中{p}%。",
"In the news with": "一緒に報じられた国",
"Countries that appeared in the same news articles most often. A sign of who the country deals with.": "同じ記事に最もよく登場した国。この国の関わり相手がわかります。",
"Ideas to copy": "まねしたいアイデア",
"Written each week by AI from the data above. Use them as starting points.": "上のデータからAIが毎週作成。出発点としてどうぞ。",
"Based on: {x}": "根拠: {x}",
"This week's ideas are being written. Check back soon.": "今週のアイデアを作成中です。また見に来てください。",
"How to read the numbers": "数字の見方",
"Views": "閲覧数",
"Times a Wikipedia page was opened from that country. Wikimedia rounds them up a little to protect privacy.": "その国からWikipediaのページが開かれた回数。プライバシー保護のため少し切り上げられています。",
"Days in the top 30": "上位30の日数",
"On how many recorded days the page was among the country's 30 most-read. More days means lasting interest, not a one-day spike.": "記録日のうち国の上位30に入った日数。多いほど一時的でない関心です。",
"Online news articles worldwide that mention the country, counted by The GDELT Project. One article can count for two countries.": "この国に触れた世界のオンライン記事。The GDELT Projectが集計し、1件が2か国に数えられることもあります。",
"Peaceful and tense news": "平和的なニュースと緊張のニュース",
"GDELT sorts every news event into 20 types. Talks, deals and aid count as peaceful. Protests and fighting count as tension or conflict.": "GDELTは出来事を20種類に分類します。会談・合意・援助は平和的、抗議・戦闘は緊張または対立として数えます。",
"Period": "期間",
"Each report covers up to the last 30 recorded days.": "各レポートは記録された直近最大30日分です。",
"Sources and limits": "出典と限界",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). Ideas are written by AI (Google Gemini) and can contain mistakes. YouTube and news headlines are not part of the report.": "Like Pollingが毎日記録した公開データから作成: Wikipediaの閲覧数(Wikimedia Foundation)、ニュースの話題と国(The GDELT Project)。アイデアはAI(Google Gemini)が書いており、誤りを含むことがあります。YouTubeやニュースの見出しは含みません。",
"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). YouTube and news headlines are not part of the report.": "Like Pollingが毎日記録した公開データから作成: Wikipediaの閲覧数(Wikimedia Foundation)、ニュースの話題と国(The GDELT Project)。YouTubeやニュースの見出しは含みません。",
