"Athletes and stars who name {s} as a sponsor on Wikipedia, ranked by English Wikipedia views, last 30 days.": "Athlètes et stars qui citent {s} comme sponsor sur Wikipédia, classés par vues sur Wikipédia en anglais, 30 derniers jours.",
