"A sponsor pays to be seen by a person's fans. The more people read about that person, in more languages, the further the brand travels.": "Un sponsor paie pour être vu par les fans d'une personne. Plus les gens lisent sur cette personne, en plus de langues, plus la marque voyage.",
"Extended Brand Report": "Rapport de marque détaillé",
"No Wikipedia page of its own yet. This report shows what the open web says about it.": "Pas encore de page Wikipédia dédiée. Ce rapport montre ce que le web ouvert dit à son sujet.",
"1 person names {s} as a sponsor on Wikipedia.": "1 personne cite {s} comme sponsor sur Wikipédia.",
