"No page was among the most-read in both countries.": "Aucune page ne figurait parmi les plus lues dans les deux pays.",
"Wikipedia views": "Vues Wikipedia",
"of the daily top 30 pages, all days added": "sur les 30 pages les plus lues par jour, tous les jours cumulés",
"about the country, worldwide": "sur le pays, dans le monde",
"talks, deals, aid. The rest is tension or conflict": "discussions, accords, aide. Le reste est tension ou conflit",
"{n} articles together": "{n} articles ensemble",
"{n} views": "{n} vues",
"New this week": "Nouveautés cette semaine",
"pages that just entered the top 30": "pages qui viennent d'entrer dans le top 30",
"At a glance": "En un coup d'œil",
"The main numbers for the period, explained in the sections below.": "Les chiffres principaux pour la période, expliqués dans les sections ci-dessous.",
"News coverage per day": "Couverture médiatique par jour",
"How many news articles worldwide mentioned the country each day. Spikes usually mean a big event.": "Combien d'articles ont mentionné le pays chaque jour. Les pics indiquent souvent un événement majeur.",
"Busiest day: {day} with {n} articles": "Journée la plus chargée : {day} avec {n} articles",
", {x}× the quietest day ({day}, {n})": ", {x}× le jour le plus calme ({day}, {n})",
". Average: {n} a day.": ". Moyenne : {n} par jour.",
"Wikipedia attention per day": "Attention Wikipedia par jour",
"Total views of the 30 most-read pages each day. It shows how busy people were looking things up.": "Total des vues des 30 pages les plus lues chaque jour. Montre à quel point les gens ont fait des recherches.",
"The #1 page, {title}, had {n} views: {p}% of all top-30 views in the period.": "La page n°1, {title}, a totalisé {n} vues : {p}% de toutes les vues du top 30 sur la période.",
"Most-read on Wikipedia": "Les plus lus sur Wikipedia",
"Total views over the period. The small line shows that page's views day by day.": "Vues totales sur la période. La petite ligne montre les vues quotidiennes de cette page.",
"Rising this week": "En hausse cette semaine",
"Pages that entered the daily top 30 only in the last 7 days. Often the best early signals.": "Pages entrées dans le top 30 quotidien seulement au cours des 7 derniers jours. Souvent les meilleurs signaux précoces.",
"{d} of {t} days in the daily top 30 · first seen {day}": "{d} sur {t} jours dans le top 30 · première apparition {day}",
"What the news talks about": "De quoi parlent les actualités",
"Share of all news articles about the country, by type of event.": "Part des articles sur le pays, par type d'événement.",
"peaceful": "pacifique",
"tension or conflict": "tension ou conflit",
"The most common type was {t}, at {p}% of {n} articles.": "Le type le plus courant était {t}, avec {p}% des {n} articles.",
"In the news with": "Dans les actualités avec",
"Countries that appeared in the same news articles most often. A sign of who the country deals with.": "Pays les plus présents dans les mêmes articles d'actualité. Un signe des relations de ce pays.",
"Ideas to copy": "Idées à copier",
"Written each week by AI from the data above. Use them as starting points.": "Rédigé chaque semaine par une IA à partir des données ci-dessus. Utilisez-les comme point de départ.",
"Based on: {x}": "Basé sur : {x}",
"This week's ideas are being written. Check back soon.": "Les idées de cette semaine sont en cours de rédaction. Revenez bientôt.",
"How to read the numbers": "Comment lire les chiffres",
"Views": "Vues",
"Times a Wikipedia page was opened from that country. Wikimedia rounds them up a little to protect privacy.": "Nombre de fois où une page Wikipédia a été ouverte depuis ce pays. Wikimedia arrondit les chiffres pour protéger la vie privée.",
"Days in the top 30": "Jours dans le top 30",
"On how many recorded days the page was among the country's 30 most-read. More days means lasting interest, not a one-day spike.": "Nombre de jours enregistrés où la page était parmi les 30 plus lues du pays. Plus le nombre est élevé, plus l'intérêt est durable.",
"Online news articles worldwide that mention the country, counted by The GDELT Project. One article can count for two countries.": "Articles d'actualité en ligne dans le monde mentionnant le pays, comptés par The GDELT Project. Un article peut compter pour deux pays.",
"Peaceful and tense news": "Actualités pacifiques et tendues",
"GDELT sorts every news event into 20 types. Talks, deals and aid count as peaceful. Protests and fighting count as tension or conflict.": "GDELT classe chaque événement en 20 types. Les discussions, accords et aides sont considérés comme pacifiques. Les manifestations et combats comptent comme tension ou conflit.",
"Period": "Période",
"Each report covers up to the last 30 recorded days.": "Chaque rapport couvre jusqu'aux 30 derniers jours enregistrés.",
"Sources and limits": "Sources et limites",
