"{s} was a trending Google search in {c}.": "{s} 是 {c} 的 Google 热门搜索词。",
"{s} was a trending Google search in {n} countries.": "{s} 是 {n} 个国家的 Google 热门搜索词。",
"Trending searches: Google Trends.": "热门搜索：Google 趋势。",
"Holidays: Nager.Date, open data.": "假期：Nager.Date，开放数据。",
"Days trending": "热门天数",
"Approx. searches": "搜索量（约）",
"Search": "搜索",
"Date": "日期",
"Holiday": "假期",
"Name in English": "英文名称",
"Compare with real rivals, not with everyone. A small brand can lead its niche and still look tiny next to the giants.": "与真正的竞争对手比较，而不是与所有人比较。一个小品牌可以领导其细分市场，但在巨头面前依然显得渺小。",
"GDP is the size of a whole economy, not how rich each person is. For that, look at GDP per person.": "GDP 是整个经济的规模，而不是每个人的富裕程度。要了解这一点，请查看人均 GDP。",
"growth of {c}'s economy in {y}, after inflation.": "{y} 年 {c} 经济增长（扣除通胀后）。",
"change in {c}'s economy in {y}, after inflation: it shrank.": "{y} 年 {c} 经济变化（扣除通胀后）：经济出现萎缩。",
"{c}'s economy grew {p}% in {y}.": "{y} 年 {c} 经济增长了 {p}%。",
"{c}'s economy shrank {p}% in {y}.": "{y} 年 {c} 经济萎缩了 {p}%。",
"GDP per person in {a} is {x}× that of {b}.": "{a} 的人均 GDP 是 {b} 的 {x} 倍。",
"GDP, US$ billions": "GDP，十亿美元",
"GDP per person, US$": "人均 GDP，美元",
"GDP, US$": "GDP, US$",
"Growth after inflation": "扣除通胀后的增长",
"The economy": "经济",
"Year": "年份",
"Yearly figures from the World Bank. The newest year is usually last year.": "世界银行的年度数据。最新年份通常是去年。",
"GDP": "GDP",
"Gross domestic product: the value of everything a country produces in a year. GDP per person is that value divided by the population. From the World Bank.": "国内生产总值：一个国家一年内生产的所有产品的价值。人均 GDP 是该价值除以人口。来源：世界银行。",
"GDP figures come from the World Bank's open data.": "GDP 数据来自世界银行的开放数据。",
"In its field": "在同领域",
"{s} is #{r} of {n} in {f}, with {p}% of the attention.": "{s} 在 {f} 中排名第 {r}（共 {n} 个），占 {p}% 的关注度。",
"Its views changed {a} this month; the whole field changed {b}.": "本月其浏览量变化了 {a}；整个领域变化了 {b}。",
"Top in its field": "同领域领先者",
"{f}: the {n} biggest pages in this Wikipedia category, ranked by English Wikipedia views, last 30 days.": "{f}：此 Wikipedia 分类中最大的 {n} 个页面，按英文 Wikipedia 浏览量排名，最近 30 天。",
"{s} in {f}, by Wikipedia views.": "{s} 在 {f} 中，按 Wikipedia 浏览量。",
"almost all": "几乎所有",
"fewer than 1 in 10": "不到1/10",
"{n} in 10": "10个中的{n}",
"Learn": "了解",
"In plain words": "用通俗的话说",
"The report in a few easy numbers. The slides after this show the details.": "用几个简单的数字看报告。后面的幻灯片展示了细节。",
"{a} was in the news {x}× as much as {b}.": "{a} 在新闻中出现的频率是 {b} 的 {x} 倍。",
"news stories about {c} were peaceful: talks, deals or aid.": "关于 {c} 的新闻是和平的：会谈、协议或援助。",
"On {day}, news about {c} was {x}× a normal day. Something big happened.": "在 {day}，关于 {c} 的新闻量是平时的 {x} 倍。发生了大事。",
"of top-30 views in {c} went to one page: {t}.": "在 {c} 的前30名浏览量中，有来自同一页面的：{t}。",
"People in {c} cared most about {t}.": "{c} 的人们最关心 {t}。",
"{t} is the newest big interest in {c}.": "{t} 是 {c} 最新关注的热点。",
"{p} shows up next to {c} in the news more than any other country.": "{p} 在新闻中与 {c} 一起出现的次数比其他任何国家都多。",
"What this means": "这意味着什么",
"{s} is followed most in {c}.": "{s} 在 {c} 中最受关注。",
"readers of {s} used a language other than English.": "{s} 的读者使用了英语以外的语言。",
"{s} had {x}× the views of {b}, the next most-viewed.": "{s} 的浏览量是排名第二的 {b} 的 {x} 倍。",
"On {day}, views of {s} were {x}× a normal day.": "在 {day}，{s} 的浏览量是平时的 {x} 倍。",
"more Wikipedia views for {s} than the month before.": "{s} 的维基百科浏览量比上个月多。",
"fewer Wikipedia views for {s} than the month before.": "{s} 的维基百科浏览量比上个月少。",
"{s} among similar artists, by views.": "按浏览量统计，{s} 在类似艺术家中的排名。",
"{s} among similar brands, by views.": "按浏览量统计，{s} 在类似品牌中的排名。",
"A good number always compares: more than what, since when, out of how many? Ask that about every stat you see online.": "好的数字总是需要对比：比什么多？从什么时候开始？总共是多少？当你在线查看任何统计数据时，都要问自己这些问题。",
"One big number means little on its own. Compare it with another country, another week or another brand.": "一个孤立的大数字意义不大。请将其与另一个国家、另一周或另一个品牌进行对比。",
"In a line chart, look for spikes, not exact numbers. A spike is a day very different from the rest: check the news for that day.": "在折线图中，要关注峰值，而不是确切数字。峰值通常代表不同寻常的一天：去查查那天的新闻吧。",
"A page that stays in the top 30 for many days shows lasting interest. A one-day jump is usually a moment, not a trend.": "在榜单前30名中停留多日的页面代表了持久的关注。一天的突增通常只是瞬间，而不是趋势。",
"New entries are early signals. Wait to see if they stay next week before acting on them.": "新上榜项是早期信号。在采取行动前，先看看它们下周是否还会上榜。",
"Percentages show shares, not size. 20% of a big country's news can be more articles than 80% of a small one's.": "百分比显示的是份额，而非规模。大国20%的新闻报道可能比小国80%的报道涉及的文章更多。",
"Two countries in the same story doesn't mean they get along. It can be trade, sport or a conflict.": "两个国家出现在同一篇新闻里并不意味着它们关系好。这可能是贸易、体育或冲突。",
"Compare like with like: same days, same source, same measure. Otherwise the comparison lies.": "只对比相同的事物：相同的日期、相同的来源、相同的衡量标准。否则对比就会误导人。",
"Where people read is a hint of where fans or customers are, not proof.": "人们阅读的地方只是暗示了粉丝或客户在哪里，而非确凿证据。",
"More days in a country's top 30 means steady interest there, not just one viral moment.": "在一个国家的榜单前30名中停留的天数越多，说明兴趣越稳定，而不仅仅是病毒式传播的瞬间。",
