"AI builders": "AI डेवलपर्स",
"The most-starred new AI project on GitHub each year from a builder in this country.": "इस देश के किसी डेवलपर द्वारा हर साल GitHub पर सबसे ज्यादा स्टार वाला नया AI प्रोजेक्ट।",
"Builders who leave their GitHub location empty can't be placed in a country, so some projects may be missing.": "जो डेवलपर्स GitHub पर अपनी लोकेशन खाली छोड़ देते हैं, उन्हें किसी देश से नहीं जोड़ा जा सकता, इसलिए कुछ प्रोजेक्ट्स छूट सकते हैं।",
"AI projects: GitHub API.": "AI प्रोजेक्ट्स: GitHub API.",
"Month": "महीना",
"In {m}, 1 in {n} news stories worldwide mentioned {s}.": "{m} में, दुनिया भर की हर {n} न्यूज़ स्टोरीज़ में से 1 में {s} का ज़िक्र था।",
"How much of the world's news mentioned {s} each month, since 2017 (100 = its busiest month).": "2017 से हर महीने दुनिया भर की न्यूज़ में {s} का कितना ज़िक्र हुआ (100 = इसका सबसे व्यस्त महीना)।",
"It was most in the news in {m}.": "{m} में यह न्यूज़ में सबसे ज्यादा था।",
"In the last 12 months, its news share changed {p} compared with the 12 months before.": "पिछले 12 महीनों में, न्यूज़ शेयर में {p} का बदलाव आया है, पिछले 12 महीनों की तुलना में।",
"A snapshot in time.": "समय का एक स्नैपशॉट।",
"This report captures {date}. Like Polling keeps a dated copy in its archive, so this moment can be compared with any later one.": "यह रिपोर्ट {date} को कैप्चर करती है। Like Polling अपने आर्काइव में एक डेटेड कॉपी रखता है, ताकि इस पल की तुलना बाद के किसी भी पल से की जा सके।",
"Next rocket launch": "अगला रॉकेट लॉन्च",
"The next rocket launch from this country. If none is planned, the next one anywhere in the world.": "इस देश से अगला रॉकेट लॉन्च। अगर कोई प्लान नहीं है, तो दुनिया में कहीं भी अगला लॉन्च।",
"Next rocket launch from {c}: {n} on {d}.": "{c} से अगला रॉकेट लॉन्च: {d} को {n}।",
"No rocket launch is planned from {c}. The next one in the world is {n} on {d}.": "{c}: कोई रॉकेट लॉन्च प्लान नहीं है। दुनिया में अगला {n} है, {d} को।",
"Rocket launches: The Space Devs (Launch Library 2).": "रॉकेट लॉन्च: The Space Devs (Launch Library 2).",
"Growth and share of attention": "ग्रोथ और अटेंशन शेयर",
"How each one did in the last 30 days, compared with the 30 days before and the same 30 days last year, and its share of all views and searches among them.": "पिछले 30 दिनों में कैसा प्रदर्शन रहा, पिछले 30 दिनों और पिछले साल के इन्हीं 30 दिनों की तुलना में, और सभी व्यूज़ और सर्च में इसका शेयर।",
"vs previous 30 days": "पिछले 30 दिनों की तुलना में",
"vs same days last year": "पिछले साल के इन्हीं दिनों की तुलना में",
