"{s} had {p}% of the Wikipedia views and {q}% of the Google searches among these {n}.": "इन {n} में से {s} का {p}% Wikipedia व्यूज़ और {q}% Google सर्च शेयर था।",
"Compared with the same 30 days last year, views of {s} changed {a}.": "पिछले साल के उन्हीं 30 दिनों की तुलना में, {s} के व्यूज़ में {a} का बदलाव आया।",
