"Yearly results {s} reports to the US regulator (SEC). Its business year may end in any month.": "{s} द्वारा अमेरिकी नियामक (SEC) को रिपोर्ट किए गए वार्षिक परिणाम। इसका वित्तीय वर्ष किसी भी महीने में समाप्त हो सकता है।",
"Shares trade on {x} as {t}.": "शेयर {x} पर {t} के रूप में ट्रेड होते हैं।",
