"In {y}, it lost money.": "{y} में, इसे नुकसान हुआ।",
"Sales are all the money customers paid. Profit is what is left after every cost and tax. High sales with low profit can still be a weak year.": "बिक्री वह पैसा है जो ग्राहकों ने चुकाया। मुनाफा वह है जो सभी खर्चों और करों के बाद बचता है। कम मुनाफे के साथ अधिक बिक्री भी एक कमजोर वर्ष हो सकता है।",
"Sales and profit: US SEC filings (EDGAR), public data.": "बिक्री और मुनाफा: अमेरिकी SEC फाइलिंग (EDGAR), सार्वजनिक डेटा।",
