"Did you mean:": "क्या आपका मतलब था:",
"A search spike shows curiosity, not love. People also search for things they fear or just heard about.": "सर्च स्पाइक जिज्ञासा दिखाता है, प्यार नहीं। लोग उन चीजों को भी सर्च करते हैं जिनसे वे डरते हैं या जिनके बारे में उन्होंने अभी सुना है।",
"On holidays people shop, travel and go online differently. Plan posts a week or two ahead.": "छुट्टियों के दौरान लोग खरीदारी, यात्रा और इंटरनेट का उपयोग अलग तरह से करते हैं। अपनी पोस्ट एक या दो हफ्ते पहले प्लान करें।",
"Searched on Google": "Google पर सर्च किया गया",
"Searches that suddenly grew on Google in the country (Google Trends). The numbers are Google's rough estimates.": "देश में Google पर अचानक बढ़ी सर्च (Google Trends)। ये संख्याएं Google का अनुमानित आंकड़ा है।",
"trending on 1 day": "1 दिन में ट्रेंडिंग",
"trending on {n} days": "{n} दिनों में ट्रेंडिंग",
"The biggest search in {c} was {q}, with about {n} searches.": "{c} में सबसे अधिक खोज {q} की गई, लगभग {n} खोजों के साथ।",
"Holidays coming up": "आगामी छुट्टियां",
"National public holidays in the next months. Good dates to plan campaigns around.": "अगले कुछ महीनों में राष्ट्रीय सार्वजनिक छुट्टियां। अभियानों की योजना बनाने के लिए अच्छी तारीखें।",
"Next holiday in {c}: {h} on {d}.": "{c} में अगली छुट्टी: {d} को {h}।",
"Trending on Google": "Google पर ट्रेंडिंग",
"Days {s} was among the trending Google searches in each country (Google Trends).": "वे दिन जब {s} प्रत्येक देश में Google ट्रेंडिंग खोजों में शामिल था (Google Trends)।",
"{s} was a trending Google search in {c}.": "{s}, {c} में एक ट्रेंडिंग Google खोज थी।",
"{s} was a trending Google search in {n} countries.": "{s}, {n} देशों में एक ट्रेंडिंग Google खोज थी।",
"Trending searches: Google Trends.": "ट्रेंडिंग खोजें: Google Trends.",
"Holidays: Nager.Date, open data.": "छुट्टियां: Nager.Date, ओपन डेटा।",
