"Online news articles worldwide that mention the country, counted by The GDELT Project. One article can count for two countries.": "दुनिया भर के ऑनलाइन समाचार लेख जो उस देश का उल्लेख करते हैं, जिसे The GDELT Project द्वारा गिना जाता है। एक लेख दो देशों के लिए गिना जा सकता है।",
