"Built by Like Polling from its own daily records of open data: Wikipedia page views (Wikimedia Foundation) and news topics and countries (The GDELT Project). YouTube and news headlines are not part of the report.": "Like Polling द्वारा अपने दैनिक ओपन डेटा रिकॉर्ड से निर्मित: विकिपीडिया पेज व्यूज (विकिमीडिया फाउंडेशन) और समाचार विषय व देश (The GDELT Project)। YouTube और समाचार हेडलाइंस रिपोर्ट का हिस्सा नहीं हैं।",
